<?php session_start();require_once 'config/conexao.php';require_once 'config/auth.php';exigir_cargo(['funcionario','gerente','administrador']);$prod=$pdo->query('SELECT id,nome,quantidade,unidade,preco FROM produtos WHERE ativo=1 ORDER BY nome')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){ $cliente=trim($_POST['cliente']??'');$ids=$_POST['produto']??[];$qts=$_POST['quantidade']??[];$obs=trim($_POST['observacoes']??'');try{$pdo->beginTransaction();$total=0;$itens=[];foreach($ids as $i=>$id){$qt=(float)($qts[$i]??0);if($qt<=0)continue;$s=$pdo->prepare('SELECT * FROM produtos WHERE id=? AND ativo=1 FOR UPDATE');$s->execute([(int)$id]);$p=$s->fetch();if(!$p||$p['quantidade']<$qt)throw new Exception('Produto inexistente ou estoque insuficiente: '.($p['nome']??''));$total+=$qt*$p['preco'];$itens[]=[$p,$qt];}if(!$itens)throw new Exception('Adicione pelo menos um produto.');$s=$pdo->prepare('INSERT INTO vendas(usuario_id,cliente,total,observacoes) VALUES(?,?,?,?)');$s->execute([$_SESSION['usuario']['id'],$cliente,$total,$obs]);$vid=$pdo->lastInsertId();foreach($itens as [$p,$qt]){$pdo->prepare('INSERT INTO venda_itens(venda_id,produto_id,quantidade,preco_unitario) VALUES(?,?,?,?)')->execute([$vid,$p['id'],$qt,$p['preco']]);$pdo->prepare('UPDATE produtos SET quantidade=quantidade-? WHERE id=?')->execute([$qt,$p['id']]);}$pdo->commit();flash('Pedido/venda registrado! Número #'.$vid);}catch(Exception $e){if($pdo->inTransaction())$pdo->rollBack();flash($e->getMessage());}header('Location: nova_venda.php');exit;}
?>
<!DOCTYPE html><html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nova venda</title><link rel="stylesheet" href="style.css"></head><body><main class="app"><header class="topbar"><h2>Registrar venda/pedido</h2><a class="link-sair" href="painel.php">← Painel</a></header><section class="content"><?php mostrar_flash();?><form class="form-box" method="post"><label>Cliente (opcional)</label><input name="cliente" placeholder="Nome do cliente"><h2>Produtos</h2><?php if(!$prod):?><p>Nenhum produto cadastrado. Solicite ao gerente o cadastro do estoque.</p><?php endif;?><?php foreach($prod as $x):?><div class="sale-item"><div><strong><?=h($x['nome'])?></strong><small>Disponível: <?=h($x['quantidade'])?> <?=h($x['unidade'])?> · R$ <?=number_format($x['preco'],2,',','.')?></small></div><input type="hidden" name="produto[]" value="<?=$x['id']?>"><label>Quantidade</label><input type="number" name="quantidade[]" min="0" step="0.01" value="0"></div><?php endforeach;?><label>Observações</label><textarea name="observacoes"></textarea><button <?=!$prod?'disabled':''?>>Registrar pedido</button></form></section></main></body></html>